import React, { useEffect, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { Card, Grid, Button, Typography, IconButton, InputAdornment, Divider, Box } from '@mui/material';
import Select from '@mui/material/Select'
import MenuItem from '@mui/material/MenuItem';
import FormControl from '@mui/material/FormControl';
// import { toast } from 'react-toastify';
import InputLabel from '@mui/material/InputLabel';
import { DemoContainer } from '@mui/x-date-pickers/internals/demo';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import dayjs from 'dayjs';  // Import dayjs for date manipulation
import CountryCode from '../../CountryCode';
import PhoneLengthByCountry from '../../PhoneLengthByCountry';
import Iconify from '../../components/iconify';
import { axios } from '../../utils/axios';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import GoBackButton from '../../components/goBackButton/GoBackButton';
import ImageUpload from '../../components/input/imageUpload';
import InputField from '../../components/input/inputField';
import useResponsive from '../../hooks/useResponsive';

const ITEM_HEIGHT = 48;
const ITEM_PADDING_TOP = 8;
const MenuProps = {
  PaperProps: {
    style: {
      maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP,
      width: 250,
    },
  },
};

export default function AddaminPage({ src }) {
  const navigate = useNavigate();
  const [code, setCode] = useState('');
  const location = useLocation();
  const [email, setEmail] = useState('');
  const [passwordemail, setPasswordemail] = useState('');
  const [fname, setFname] = useState('');
  const [lname, setLname] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [emailError, setEmailError] = useState('');
  const [phoneNumberError, setPhoneNumberError] = useState('');
  const [error, setError] = useState('');
  const [gender, setGender] = useState('');
  const [dob, setDOB] = useState(null);
  const [firstname, setFirstname] = useState(false);
  const [lastname, setLastname] = useState(false);
  const [profilePhoto, setProfilephoto] = useState('');
  const [selectedCountry, setSelectedCountry] = useState(null);
  const [phone, setPhone] = useState('');
  const [images, setImg] = useState("");
  const [adminRoleList, setAdminRolesList] = useState([]);
  const [selectedRole, setSelectedRole] = useState("");
  const { i18 } = useMyContext()
  const isMobile = useResponsive("down", "sm")

  useEffect(() => {
    adminRoles();
  }, []);

  const adminRoles = async() => {
    try{
      const url = `module/auth/adminRole/list`
      const response = await axios.get(url);
      if(response?.status === 200) {
        setAdminRolesList(response?.data?.data?.adminRoleData)
      }
    } catch (error) {
      console.error(error);
    }
  }

  const handleRoleChange = (event) => {
    const adminRole = adminRoleList?.find(c => c?.value === event.target.value);
    setSelectedRole(adminRole?.value)
  }

  const handleCountryChange = (event) => {
    const country = CountryCode.find(c => c.dial_code === event.target.value);
    setSelectedCountry(country);
    setCode(country.dial_code);
    setPhone('');
  };

  const handlePhoneNumberChange = (event) => {
    const { value } = event.target;
    if (/^\d*$/.test(value)) { // Allow only digits
      setPhone(value);
      if (selectedCountry && value.length !== PhoneLengthByCountry[selectedCountry.code]) {
        setPhoneNumberError('Invalid Phone Number')
      } else {
        setPhoneNumberError('');
      }
    }
  };
  
  const handleUploadedFile = (event) => {
    const file = event.target.files[0];
    setImg(file)
  }

  const getPhoneNumberInput = () => {
    if (selectedCountry) {
      const maxLength = PhoneLengthByCountry[selectedCountry.code];
      return (
        <InputField
          value={phone}
          sx={{
            margin: '10px 0px',
            width: '100%',
            '& .MuiInputBase-input.MuiOutlinedInput-input': {
              padding: '10.5px 14px !important'
            }
          }}
          label={i18?.ACCOUNTSTITLE?.PHONE_NUMBER || "Phone Number"}
          onChange={handlePhoneNumberChange}
          inputProps={{ inputMode: 'numeric', pattern: '[0-9]*', maxLength }}
          error={!!phoneNumberError}
          helperText={phoneNumberError}
          required
        />
      );
    }
    return (
      <InputField
        value={phone}
        label={i18?.ACCOUNTSTITLE?.PHONE_NUMBER || "Phone Number"}
        sx={{
          margin: '10px 0px',
          width: '100%',
          '& .MuiInputBase-input.MuiOutlinedInput-input': {
            padding: '10.5px 14px !important'
          }
        }}
        onChange={handlePhoneNumberChange}
      />
    )
  };

  const types = location?.state?.types;

  const AddButtonDis = !email || !passwordemail || !fname || !gender;
  const backtouser = () => {
    if (types === 'Admin') {
      navigate('/dashboard/admin');
    } else if (types === 'User') {
      navigate('/dashboard/user');
    } else {
      navigate('/dashboard/provider');
    }
  };

  const addProfile = async () => {
    try {
      if (types === 'Admin') {
        const formData = new FormData();
        formData.append('firstname', fname);
        formData.append('lastname', lname);
        formData.append('phoneCode', code);
        formData.append('phone', phone);
        formData.append('dob', dob);
        formData.append('gender', gender);
        formData.append('email', email);
        formData.append('password', passwordemail);
        formData.append('file', images);
        formData.append('role', selectedRole);

        const res = await axios.post('module/auth/admin', formData);
        if (res.status === 201) {
          GenerateToastConfig(res.data.message, 'success');
          navigate('/dashboard/admin');
          setFname("")
          setLname("")
          setCode("")
          setPhone("")
          setDOB("")
          setGender("")
          setEmail("")
          setPasswordemail("")
          setProfilephoto("")
        } else {
          GenerateToastConfig(res.data.message);
        }

      } else if (types === 'User') {
        const formData = new FormData();
        formData.append('firstname', fname);
        formData.append('lastname', lname);
        formData.append('phoneCode', code);
        formData.append('phone', phone);
        formData.append('dob', dob);
        formData.append('gender', gender);
        formData.append('email', email);
        formData.append('password', passwordemail);
        formData.append('file', images);

        const res = await axios.post('module/auth/admin/addUser', formData);

        if (res.status === 201) {
          GenerateToastConfig(res.data.message, 'success');
          navigate('/dashboard/user');
        } else {
          GenerateToastConfig(res.data.message);
        }
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const handleInputChange = (event) => {
    const { value } = event.target;
    if (/^[A-Za-z\s]*$/.test(value)) { // Allow only letters and spaces
      setFname(value);
      if (value.length < 2) { // Example validation: name should be at least 2 characters long
        setError('Name is too short');
      } else {
        setError('');
      }
    }
  };

  const handleNameChange = (event) => {
    const { value } = event.target;
    if (/^[A-Za-z\s]*$/.test(value)) {
      setLname(value);
      if (value.length < 2) {
        setError('Name is too short');
      } else {
        setError('')
      }
    }
  };

  const today = dayjs();
  const startOfCurrentYear = today.startOf('year');
  const endOfPreviousYear = startOfCurrentYear.subtract(1, 'year').endOf('year');

  const handleDOBChange = (date) => {
    setDOB(date);
  };

  const getMaxDate = () => {
    // If today is within the current year, set maxDate to December 31 of the previous year
    return today.isAfter(startOfCurrentYear) || today.isSame(startOfCurrentYear, 'year')
      ? endOfPreviousYear
      : today;
  };

  // const getMaxDate = () => {
  //   // If today is within the current year, set maxDate to December 31 of the previous year
  //   return today.isAfter(startOfCurrentYear) || today.isSame(startOfCurrentYear, 'year')
  //     ? endOfPreviousYear
  //     : today;
  // };

  const handleMailChange = (e) => {
    const emailInput = e.target.value;
    setEmail(emailInput);

    if (!/[a-z0-9]+@[^\s@]+\.[a-z]{3}$/.test(emailInput)) {
      setEmailError('Invalid email format');
    } else if (/[!#$%^&*()_+|[\]{};:'"<>,?,]/.test(emailInput)) {
      setEmailError('Invalid email format');
    } else {
      setEmailError('');
    }
  };
  return (
    <>
      <Helmet>
        <title>{`Add ${types}`}</title>
      </Helmet>

      <Card >
        <Grid container sx={{ padding: '10px 30px', margin: '10px 0px' }}>
          <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
            <Box sx={{ display: "flex", alignItems: "center" }}>
              <Box
                sx={{
                  width: '37px',
                  height: '37px',
                  background: '#FF5A60',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderRadius: '50%',
                  cursor: 'pointer'
                }}
                onClick={backtouser} >
                <Iconify icon={"mdi:arrow-left"} width={24} height={24} color="white" />
              </Box>
              <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                {types === "Admin" ? i18?.ACCOUNTSTITLE?.ADD_ADMIN || "Add Admin" : i18?.ACCOUNTSTITLE?.ADD_USER || "Add User"}
              </Typography>
            </Box>
            {/* <Box sx={{ display: "flex", alignItems: "center" }}>
              <Box
                sx={{
                  width: '37px',
                  height: '37px',
                  background: '#FF5A60',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderRadius: '50%',
                  cursor: 'pointer'
                }}
                 >
                <Iconify icon={"mdi:dots-vertical"} width={24} height={24} color="white" />
              </Box>
            </Box> */}
          </Grid>
        </Grid>
        {/* <Grid container sx={{ padding: '10px 0px' }}>
          <Grid container item justifyContent="space-between" alignItems="center" sx={{ marginRight: '10px' }}>
            <Box sx={{ display: "flex", alignItems: "center" }}>
              <Box
                sx={{
                  width: '37px',
                  height: '37px',
                  background: '#FF5A60',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderRadius: '50%',
                  cursor: 'pointer'
                }}
                onClick={backtouser} >
                <Iconify icon={"mdi:arrow-left"} width={24} height={24} color="white" />
              </Box>
              <Typography variant="h6" gutterBottom sx={{ margin: '0px 0px 0px 10px', paddingBottom: '0px' }}>
                {types === "Admin" ? i18?.ACCOUNTSTITLE?.ADD_ADMIN || "Add Admin" : i18?.ACCOUNTSTITLE?.ADD_USER || "Add User"}
              </Typography>
            </Box>
            <GoBackButton
              label={i18?.ACCOUNTSTITLE?.GO_BACK || "Go Back"}
              onClick={backtouser}
              icon="icon-park-twotone:back"
            />
          </Grid>
        </Grid> */}
        <Divider sx={{ backgroundColor: "#333", margin: "10px 0px 10px 0px" }} />
        <Grid container={!isMobile} sx={{ padding: '10px 30px', margin: '10px 0px' }}>
          <Grid container={!isMobile} sx={{ marginTop: '10px' }}>
            <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px 10px 0px' : '0px 5px'}}>
              <InputField
                value={fname}
                name="firstname"
                label={i18?.ACCOUNTSTITLE?.FIRST_NAME || "First Name"}
                sx={{
                  margin: '10px 0px',
                  width: '100%',
                  '& .MuiInputBase-input.MuiOutlinedInput-input': {
                    padding: '10.5px 14px'
                  },
                }}
                onChange={handleInputChange}
                type="firstname"
                error={firstname}
                helperText={firstname}
                // helperText={error || firstname}
                required
              />
            </Grid>
            <Grid item xs={6} sx={{ padding: !isMobile ? '10px 5px 10px 50px' : '10px 0px'}}>
              <InputField
                value={lname}
                name="lastname"
                label={i18?.ACCOUNTSTITLE?.LAST_NAME || "Last Name"}
                sx={{
                  margin: '10px 0px',
                  width: '100%',
                  '& .MuiInputBase-input.MuiOutlinedInput-input': {
                    padding: '10.5px 14px'
                  }
                }}
                onChange={handleNameChange}
                type="lastname"
                error={lastname}
                helperText={lastname}
              />
            </Grid>
          </Grid>
          <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px  10px 0px' : '0px 5px' }}>
            <InputLabel sx={{ color: "#2B3343" }} id="demo-simple-select-label">{i18?.ACCOUNTSTITLE?.PHONE_CODE || "Phone Code"}</InputLabel>
            <FormControl sx={{ marginTop: '10px' }} fullWidth>
              <Select
                labelId="demo-simple-select-label"
                id="demo-simple-select"
                sx={{
                  width: '100%',
                  '& .MuiInputBase-input.MuiOutlinedInput-input': {
                    padding: '10.5px 14px'
                  }
                }}
                value={code}
                onChange={handleCountryChange}
                MenuProps={MenuProps}
                required
              >
                {CountryCode.map((data) => (
                  <MenuItem key={data.code} value={data.dial_code}>{data.name} &nbsp;&nbsp; {data.dial_code}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={6} sx={{ padding: !isMobile ? '10px 5px  10px 50px' : '10px 0px' }}>
            {getPhoneNumberInput()}
          </Grid>

          <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px  10px 0px' : '0px 5px' }}>
            <InputLabel sx={{ color: "#2B3343" }}>{i18?.ACCOUNTSTITLE?.DATE_OF_BIRTH || "Date Of Birth"}</InputLabel>
            <LocalizationProvider dateAdapter={AdapterDayjs}>
              <DemoContainer components={['DatePicker']}>
                <DatePicker
                  value={dob}
                  maxDate={getMaxDate()} // Dynamically adjust the maxDate
                  onChange={handleDOBChange}
                  sx={{
                    margin: '10px 0px',
                    width: '100%',
                    '& .MuiInputBase-input.MuiOutlinedInput-input': {
                      padding: '10.5px 14px'
                    }
                  }}
                />
              </DemoContainer>
            </LocalizationProvider>
          </Grid>
          <Grid item xs={6} sx={{ padding: !isMobile ? '10px 5px  10px 50px' : '10px 0px'}}>
            <InputLabel sx={{ color: "#2B3343" }}>{i18?.ACCOUNTSTITLE?.GENDER || "Gender"}</InputLabel>
            <Select
              sx={{
                margin: '10px 0px',
                width: '100%',
                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                  padding: '10.5px 14px'
                },
              }}
              value={gender}
              onChange={(e) => setGender(e.target.value)}
              required
            >
              <MenuItem value="male">Male</MenuItem>
              <MenuItem value="female">Female</MenuItem>
              <MenuItem value="other">Other</MenuItem>
            </Select>
          </Grid>

          <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px  10px 0px' : '0px 5px' }}>
            <InputField
              value={email}
              name="EmailAddress"
              label={i18?.ACCOUNTSTITLE?.EMAIL || "Email"}
              sx={{
                margin: '10px 0px',
                width: '100%',
                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                  padding: '10.5px 14px'
                }
              }}
              onChange={handleMailChange}
              type="email"
              error={!!emailError}
              helperText={emailError}
              required
            />
          </Grid>
          <Grid item xs={6} sx={{ padding: !isMobile ? '10px 5px  10px 50px' : '10px 0px' }}>
            <InputField
              value={passwordemail}
              name="passwordemail"
              type={showPassword ? 'text' : 'password'}
              label={i18?.ACCOUNTSTITLE?.PASSWORD || "Password"}
              sx={{
                margin: '10px 0px',
                width: '100%',
                '& .MuiInputBase-input.MuiOutlinedInput-input': {
                  padding: '10.5px 14px'
                }
              }}
              onChange={(e) => setPasswordemail(e.target.value)}
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton onClick={() => setShowPassword(!showPassword)} edge="end">
                      <Iconify icon={showPassword ? 'eva:eye-fill' : 'eva:eye-off-fill'} />
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />
          </Grid>
          
          <Grid item xs={6} sx={{ padding: !isMobile ? '10px 50px  10px 0px' : '0px 5px' }}>
            <InputLabel sx={{ color: "#2B3343" }} id="demo-simple-select-label">{i18?.ACCOUNTSTITLE?.PROFILE_PIC || 'Profile Pic'}</InputLabel>
            <ImageUpload value={images} onChange={handleUploadedFile} />
          </Grid>
          {types === "Admin" && <Grid item xs={6} sx={{ padding: !isMobile ? '10px 5px  10px 50px' : '10px 0px' }}>
            <InputLabel sx={{ color: "#2B3343" }} id="demo-simple-select-label">{i18?.ACCOUNTSTITLE?.SELCETROLE || "Select Role"}</InputLabel>
            <FormControl sx={{ marginTop: '10px' }} fullWidth>
              <Select
                labelId="demo-simple-select-label"
                id="demo-simple-select"
                sx={{
                  width: '100%',
                  '& .MuiInputBase-input.MuiOutlinedInput-input': {
                    padding: '10.5px 14px'
                  }
                }}
                value={selectedRole}
                onChange={handleRoleChange}
                MenuProps={MenuProps}
                required
              >
                {adminRoleList?.map((data) => (
                  <MenuItem key={data?.label} value={data?.value}>{data?.label}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>}
        </Grid>
        <Divider sx={{ backgroundColor: "#333", margin: "10px 0px 10px 0px", width: "100%" }} />
          <Grid container justifyContent="flex-start" sx={{ padding: '10px 30px', margin: '10px 0px' }}>
            <Button sx={{
              padding: "10px 58px 10px 58px"
            }}
              variant="contained" disabled={AddButtonDis} onClick={() => addProfile()}>
              {i18?.ACCOUNTSTITLE?.ADD || "Add"}
            </Button>
          </Grid>
      </Card>
    </>
  );
}
